Aşağıdaki fonksiyon çağrısının sonucu nedir?
int f(int x) {
    return x + 1;
    x = x + 100;
}
printf("%d", f(2));

Aşağıdaki C kodunda printf hangi karakteri yazar?

char s[] = "ABCDE";
int i = 2;
printf("%c", s[i + 1]);

Aşağıdaki C kodu için doğru değerlendirme hangisidir?
int main(void) {
    int x = 3;
    {
        int x = 8;
        printf("%d ", x);
    }
    printf("%d", x);
}

Aşağıdaki C kodu hangi çıktıyı üretir?

for (int i = 1; i <= 3; i++) {
    for (int j = 1; j <= 3; j++) {
        if (i == j) continue;
        printf("%d%d", i, j);
    }
}

Aşağıdaki yapının zaman karmaşıklığı hangisidir?

for (i = 1; i <= n; i++)
    for (j = 1; j <= i; j = j * 2)
        islem();
